def compute(vars):
    average = (vars["v1"] + vars["v2"] + vars["v3"]) / 3
    return {
        "value": average,
        "trace": {
            "values": [vars["v1"], vars["v2"], vars["v3"]],
            "count": 3,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
